using Marketplace.Domain.Common; namespace Marketplace.Domain.Finance; public sealed class Settlement:AggregateRoot<long>{private Settlement(){}public long SellerId{get;private set;}public long AmountIRR{get;private set;}public SettlementStatus Status{get;private set;}public long BankAccountId{get;private set;}public string BankNameSnapshot{get;private set;}=null!;public string IbanSnapshot{get;private set;}=null!;public string AccountHolderNameSnapshot{get;private set;}=null!;public string? Reference{get;private set;}public string? FailureReason{get;private set;}public DateTime RequestedAtUtc{get;private set;}public DateTime? CompletedAtUtc{get;private set;}public static Settlement Create(long id,long sellerId,long amount,long bankId,string bank,string iban,string holder){if(amount<=0||string.IsNullOrWhiteSpace(iban)||string.IsNullOrWhiteSpace(holder))throw new DomainException("Invalid settlement.");return new(){Id=id,SellerId=sellerId,AmountIRR=amount,BankAccountId=bankId,BankNameSnapshot=bank,IbanSnapshot=iban,AccountHolderNameSnapshot=holder,Status=SettlementStatus.Requested,RequestedAtUtc=DateTime.UtcNow};}public void MarkProcessing(){Require(SettlementStatus.Requested);Status=SettlementStatus.Processing;}public void Complete(string reference){if(Status is not SettlementStatus.Processing)throw new DomainException("Settlement is not processing.");Status=SettlementStatus.Completed;Reference=reference;CompletedAtUtc=DateTime.UtcNow;}public void Fail(string reason){if(Status is SettlementStatus.Completed or SettlementStatus.Cancelled)throw new DomainException("Settlement is terminal.");Status=SettlementStatus.Failed;FailureReason=reason;}public void Cancel(){if(Status is SettlementStatus.Completed)throw new DomainException("Settlement is completed.");Status=SettlementStatus.Cancelled;}public void PutOnHold(){if(Status is SettlementStatus.Completed or SettlementStatus.Cancelled)throw new DomainException("Settlement is terminal.");Status=SettlementStatus.OnHold;}private void Require(SettlementStatus s){if(Status!=s)throw new DomainException("Invalid settlement state.");}}
